import java.util.*;

public class Main {
    static int findPoisonedDurationBrute(int[] timeSeries, int duration) {
        Set<Integer> poisoned = new HashSet<>();
        for (int t : timeSeries) {
            for (int sec = t; sec < t + duration; sec++) {       // mark every individual second
                poisoned.add(sec);
            }
        }
        return poisoned.size();
    }
}

