def find_poisoned_duration(time_series, duration):
    if not time_series:
        return 0
    total = 0
    for i in range(1, len(time_series)):
        total += min(duration, time_series[i] - time_series[i - 1])   # capped contribution
    return total + duration                                             # last attack's full duration

